UPDATE businesses SET description = 'BPM Toolcraft is a hardware and tool shop at 95 Victoria Road in Southfield, part of the Plumstead area, offering what it describes as the largest range of quality power tools, fine hand tools, and stationary woodworking machinery and accessories in stock and on display in South Africa. The shop trades under the Toolcraft brand and is based in Cape Town.

Customers can view the full range in store, with items on display rather than only available to order. The shop trades on weekdays and is closed over the weekend.

It suits tradespeople and woodworking enthusiasts who want to see a large range of power and hand tools in person before buying.', source_urls = json_insert(CASE WHEN json_valid(source_urls) AND json_type(source_urls) = 'array' THEN source_urls ELSE '[]' END, '$[#]', 'https://www.cylex.net.za/company/bpm-toolcraft-23706862.html'), description_enriched_at = datetime('now') WHERE slug = 'bpm-toolcraft-southfield' AND description = 'BPM Toolcraft is a specialist power tool and hardware retailer that has traded in the southern suburbs since the 1970s, stocking major brands such as Festool, Makita, Metabo, Bosch and Hikoki for both industry professionals and retail customers. It launched an online sales division in 2016 that grew into one of South Africa''s largest online power tool suppliers and wholesalers, and moved into its current larger premises on Victoria Road in 2017.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
  AND owner_user_id IS NULL AND COALESCE(subscription_tier, 0) = 0 AND COALESCE(origin, '') != 'owner_submitted'
  AND status = 'published' AND closed_at IS NULL AND is_test = 0
  AND custom_blocks IS NULL AND page_html IS NULL
  AND NOT EXISTS (SELECT 1 FROM business_claims c WHERE c.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM subscriptions s WHERE s.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM business_photos p WHERE p.business_id = businesses.id);
